from sphinx.application import Sphinx

# -- Project information -----------------------------------------------------

project = "SOAP"
author = "Rob McGibbon, Bert Vandenbroucke, John Helly, Joop Schaye, Matthieu Schaller"

# -- General configuration ---------------------------------------------------

extensions = [
    # Dropdowns in the property table
    "sphinx_design",
    # Render equations more quickly, which is needed for our large property tables
    "sphinxcontrib.katex",
]

templates_path = ["_templates"]
